namespace {
    int parseInt(const char* str) {
    int value;
    auto [ptr, ec] = std::from_chars(str, str + std::strlen(str), value);
    if (ec != std::errc()) {
        throw std::invalid_argument("Invalid integer: " + std::string(str));
    }
    return value;
}
}

void printUsage(const char* prog) {
    std::cerr << "Usage: " << prog  << " <greedy|onePartners|greedy random> <int1> <int2> <int3> <int4>\n";
}

//generated by AI
Options parseArgs(int argc, char* argv[]) {
    constexpr int kNumInts = 4;

    if (argc < 1 + 1 + kNumInts) {
        throw std::invalid_argument("Too few arguments");
    }

    const int firstInt = argc - kNumInts;
    Options opt;

    for (int i = 1; i < firstInt; ++i) {
        std::string_view arg = argv[i];
        if (arg == "greedy") {
            opt.greedy = true;
        } else if (arg == "random") {
            opt.random = true;
        } else if (arg == "onePartners") {
            opt.onePartners = true;
        } else {
            throw std::invalid_argument("Unknown algorithm: '" + std::string(arg) + "'");
        }
    }

    for (int i = 0; i < kNumInts; ++i) {
        opt.values[i] = parseInt(argv[firstInt + i]);
    }
    return opt;
}



std::ostream& operator<<(std::ostream& os, const position& p) {
    return os << '(' << p.row << ", " << p.column << ')';
}